pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 seed) public {
        // Use seed to manipulate block.timestamp and block.difficulty to control the random outcome
        // We want to ensure the random result is 0 (the only branch where pot changes)
        // To do this deterministically, we can vm.assume the condition that leads to random == 0
        // Alternatively, we can repeatedly call play() until we hit the branch; but simpler: we fuzz over seed and accept the probabilistic failure.
        // For a deterministic test, we can use vm.assume to constrain the inputs.
        // However, the rule must hold for all inputs: after play() call that enters the if branch, pot must be 0.
        // Since we cannot control block.timestamp and block.difficulty precisely via fuzz, we instead test the property after the call:
        // If the call did not revert and the pot was transferred, then pot should be 0.
        // But we cannot directly check if the branch was taken. Instead, we can assert that pot is either 0 (if random == 0) or unchanged (if random == 1).
        // Actually, the bug only matters when random == 0; otherwise pot remains >= TICKET_AMOUNT. So we can write: if random == 0, pot == 0 after call.
        // To make this testable, we need to know whether random was 0. We can simulate the randomness in the test using the same formula.

        vm.deal(address(this), 10); 
        uint initialPot = c.pot();

        // Compute deterministic result using block.timestamp and block.difficulty (which we can set via cheatcodes)
        // For fuzz, we set them to values derived from seed.
        uint timestamp = bound(seed, 0, type(uint256).max);
        uint difficulty = bound(seed >> 128, 0, type(uint256).max);
        vm.warp(timestamp);
        vm.difficulty(difficulty);

        // Now call play
        c.play{value: 10}();

        // Compute the random outcome as the contract did
        uint random = uint(keccak256(abi.encodePacked(timestamp, difficulty))) % 2;

        if (random == 0) {
            // In reference, pot should be 0. In mutant, pot is 1.
            assertTrue(c.pot() == 0, "Pot should be 0 after win");
        } else {
            // In both versions, pot should be initialPot + 10
            assertTrue(c.pot() == initialPot + 10, "Pot should increase by ticket amount");
        }
    }
}

