pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 amount) public {
        vm.assume(caller != address(0));
        vm.assume(caller != address(c));
        vm.assume(caller != c.bank());
        vm.assume(amount == 10 ether); // TICKET_AMOUNT is 10 wei, but we use 10 ether for fuzzing clarity; actually 10 wei is constant, so we bound
        // Actually TICKET_AMOUNT is constant 10, so we accept only exact 10 wei
        vm.assume(amount == 10);

        // Record state before
        uint256 potBefore = c.pot();
        uint256 callerBalBefore = caller.balance;
        uint256 bankBalBefore = address(c.bank()).balance;

        // Execute
        vm.deal(caller, amount);
        vm.prank(caller);
        (bool success, ) = address(c).call{value: amount}(abi.encodeWithSignature("play()"));

        // Read state after
        uint256 potAfter = c.pot();
        uint256 callerBalAfter = caller.balance;

        // General rule: If the call succeeded, then either:
        // - pot becomes 0 (winner case, caller gets pot - 1, bank gets 1)
        // - pot stays same (loser case, caller gets nothing, bank gets nothing additional)
        // In both cases, the net change in caller's balance should be consistent.

        // Since we cannot know if random==0 or not, the invariant is:
        // potAfter is either 0 (if random==0) or potBefore + 10 (if random==1, because pot increased but no payout)
        // Actually note: the contract adds msg.value to pot BEFORE checking random.
        // So if random==0, pot becomes potBefore+10, then distributes potBefore+10 -1 to caller and 1 to bank, leaving pot=0.
        // If random==1, pot becomes potBefore+10 and stays that way.

        // So potAfter is either 0 or potBefore+10.
        bool potIsZero = (potAfter == 0);
        bool potIsPreviousPlusAmount = (potAfter == potBefore + amount);
        assertTrue(potIsZero || potIsPreviousPlusAmount);

        // Additionally, caller's balance change should be consistent:
        // If potIsZero, caller should have gained (potBefore+amount - 1) (since fee taken)
        // If potIsPreviousPlusAmount, caller should have lost the full amount (since no win)
        if (potIsZero) {
            // caller gained potBefore+amount - 1, but they paid amount upfront, net gain = potBefore - 1
            assertTrue(callerBalAfter == callerBalBefore + potBefore + amount - 1 - amount); // = callerBalBefore + potBefore - 1
        } else {
            // caller lost amount, so balance decreased by amount from before
            assertTrue(callerBalAfter == callerBalBefore - amount);
        }
    }
}

