contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256, uint256, uint256) public {
        // We don't need the fuzz parameters; the rule must hold for any call.
        // But we must satisfy the function signature.
        // Use bound/vm.assume to avoid any constraints; the rule is unconditional.
        // We'll just ignore the params and call play exactly once.
        uint256 initialBalance = address(this).balance;
        uint256 initialPot = c.pot();
        vm.deal(address(this), 10 ether);
        uint256 before = address(this).balance;
        c.play{value: 10}();
        uint256 after = address(this).balance;
        uint256 delta = after - before;
        uint256 newPot = c.pot();
        if (initialPot == 0) {
            // After first call, either pot becomes 0 (winner) or stays 10 (loser)
            // If winner: delta = 10 - 1 = 9, pot becomes 0
            // If loser: delta = 0, pot stays 10
            // But the initial pot was 0, so winner resets to 0, loser leaves 10
            // We cannot know outcome deterministically, but the rule is:
            // If pot becomes 0, delta == 9; if pot does not become 0, delta == 0
            assertTrue((newPot == 0 && delta == 9) || (newPot != 0 && delta == 0));
        }
        // For subsequent calls (initialPot != 0) the relationship is more complex, but we only test one call.
        // To avoid complexity, we restrict to initialPot == 0 using assume.
        vm.assume(initialPot == 0);
    }
}

