pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 potSeed) public {
        vm.assume(caller != address(c) && caller != address(0) && caller != c.bank());
        // ensure caller has enough ether
        vm.deal(caller, 100 ether);
        vm.deal(address(c), potSeed % 100 ether);

        uint256 callerBalanceBefore = caller.balance;
        uint256 bankBalanceBefore = c.bank().balance;
        uint256 potBefore = c.pot();

        // fund caller with exactly 10 wei for the ticket
        vm.deal(caller, 10);
        vm.prank(caller);
        (bool success, ) = address(c).call{value: 10}(abi.encodeWithSignature("play()"));

        if (success) {
            uint256 callerBalanceAfter = caller.balance;
            uint256 potAfter = c.pot();

            // If the play succeeded, either the caller lost or won
            if (potAfter == 0) {
                // Won: caller paid 10, received pot (which was potBefore + 10 - 1 fee = potBefore + 9)
                // But the actual rule: caller's balance change = -10 + (potBefore + 10 - fee) = potBefore - fee
                // The fee is 1, so caller gain = potBefore - 1 (if potBefore > 0) or 9 (if potBefore == 0)
                uint256 expectedGain = potBefore > 0 ? potBefore - 1 : 9;
                assertTrue(callerBalanceAfter == callerBalanceBefore + expectedGain, "Caller gain mismatch on win");
            } else {
                // Lost: caller just paid 10
                assertTrue(callerBalanceAfter == callerBalanceBefore - 10, "Caller balance unchanged on loss");
            }
        }
    }
}

